"""RetinaScan XAI: Kaggle Grad-CAM audit + demo image export (generated by build_kernel.py --stage audit)."""
import base64, io, json, shutil, subprocess, sys, tarfile
from pathlib import Path

CONFIG = json.loads(r'''__CONFIG__''')
CODE_B64 = "__CODE_B64__"
CODE, ART, OUT = Path("/tmp/rs_code"), Path("/tmp/rs_art"), Path("/kaggle/working/audit")


def main():
    for d in (CODE, ART, OUT):
        d.mkdir(parents=True, exist_ok=True)
    tarfile.open(fileobj=io.BytesIO(base64.b64decode(CODE_B64))).extractall(CODE)
    prev = next(p.parent for p in Path("/kaggle/input").rglob("model.pt") if (p.parent / "train_index.npz").exists())
    for f in prev.iterdir():
        if f.is_file():
            shutil.copy(f, ART / f.name)
    img_dir = next(c.parent / "train_images" for c in Path("/kaggle/input").rglob("train.csv")
                   if (c.parent / "train_images").is_dir())
    cmd = [sys.executable, "-u", "cam_audit.py", "--artifacts", str(ART), "--img_dir", str(img_dir),
           "--out", str(OUT), "--export_ids", CONFIG.get("export_ids", "")]
    print("$", " ".join(cmd), flush=True)
    rc = subprocess.run(cmd, cwd=CODE).returncode
    if rc:
        raise SystemExit(f"cam_audit failed ({rc})")


if __name__ == "__main__":
    main()
